    .{ .name = "cwe-351", .alias = "CWE-351", .advice = "Check the exact type before deciding.", .severity = .warning, .tier = .default, .question = "Does the function fail to distinguish between different kinds of values or elements, such as treating a string and a number, a file and a directory, or two message types, as the same in a security decision?", .judgement = "Different kinds of values are treated alike in a security decision", .asks = .function },
    .{ .name = "cwe-353", .alias = "CWE-353", .advice = "Add a MAC, signature or checksum and verify it on receipt.", .severity = .warning, .tier = .default, .question = "Does the function send or receive data over a protocol or format without any integrity check, such as a checksum, MAC or signature, where corruption or tampering matters?", .judgement = "Data has no integrity check", .asks = .function },
    .{ .name = "cwe-354", .alias = "CWE-354", .advice = "Recompute it and compare, rejecting data that does not match.", .severity = .@"error", .tier = .default, .question = "Does the function receive a checksum, MAC or integrity value with data but not verify it, or verify it incorrectly, before using the data?", .judgement = "The integrity value is not checked, or is checked wrongly", .asks = .function },
    .{ .name = "cwe-356", .alias = "CWE-356", .advice = "Warn the user and ask for confirmation first.", .severity = .information, .tier = .default, .question = "Does the function perform a dangerous or irreversible action on the user's behalf, such as deleting data, running downloaded code or sending money, without warning the user first?", .judgement = "A dangerous action runs without warning the user", .asks = .function },
    .{ .name = "cwe-357", .alias = "CWE-357", .advice = "Make it prominent and require an explicit choice.", .severity = .information, .tier = .default, .question = "Does the function present a warning about a dangerous operation in a way the user is likely to miss, such as a hidden, default-accepted or easily dismissed prompt?", .judgement = "The warning about a dangerous action is easy to miss", .asks = .function },
    .{ .name = "cwe-358", .alias = "CWE-358", .advice = "Implement every check the standard requires, or use a vetted library.", .severity = .@"error", .tier = .default, .question = "Does the function implement a standard protocol, algorithm or technique but omit or get wrong one of its required security checks?", .judgement = "A security check required by the standard is missing or wrong", .asks = .function },
    .{ .name = "cwe-359", .alias = "CWE-359", .advice = "Check authorisation and consent, and return only what is permitted.", .severity = .@"error", .tier = .default, .question = "Does the function expose personal information, such as names, addresses, health, financial or location data, to users or systems that are not authorised or did not get consent to see it?", .judgement = "Personal information is exposed to someone not authorised to see it", .asks = .function },
    .{ .name = "cwe-360", .alias = "CWE-360", .advice = "Verify the sender before acting on the event.", .severity = .warning, .tier = .default, .question = "Does the function trust system events, messages or notifications as proof of their origin, without verifying who sent them?", .judgement = "Events are trusted without checking who sent them", .asks = .function },
    .{ .name = "cwe-366", .alias = "CWE-366", .advice = "Protect it with a lock, or use atomic operations.", .severity = .@"error", .tier = .default, .question = "Does the function read or modify data shared between threads without a lock, atomic operation or other synchronisation?", .judgement = "Shared data is used across threads without synchronisation", .asks = .function },
    .{ .name = "cwe-367", .alias = "CWE-367", .advice = "Act on it atomically, or check through the handle you then use.", .severity = .@"error", .tier = .default, .question = "Does the function check a property of a file or resource, such as existence, permissions or ownership, and then use it separately, so the resource could change between the check and the use?", .judgement = "The resource can change between the check and the use", .asks = .function },
    .{ .name = "cwe-368", .alias = "CWE-368", .advice = "Make the switch atomic, or block access until it completes.", .severity = .warning, .tier = .default, .question = "Does the function switch between security contexts, such as users, origins or privilege levels, through several non-atomic steps that another actor could act during?", .judgement = "Another actor can act in the middle of this context switch", .asks = .function },
    .{ .name = "cwe-372", .alias = "CWE-372", .advice = "Track the state explicitly and check it before acting.", .severity = .warning, .tier = .default, .question = "Does the function decide which state it is in from incomplete information, so it could act as if in one state while actually in another, such as treating a pending request as complete?", .judgement = "The code can mistake which state it is in", .asks = .function },
    .{ .name = "cwe-374", .alias = "CWE-374", .advice = "Pass a copy or an immutable view.", .severity = .warning, .tier = .default, .question = "Does the function pass a mutable object that it relies on, such as an internal list or buffer, to untrusted or external code without copying it first?", .judgement = "Untrusted code receives a mutable object this code relies on and can change it", .asks = .function },
    .{ .name = "cwe-375", .alias = "CWE-375", .advice = "Return a copy or an immutable view.", .severity = .warning, .tier = .default, .question = "Does the function return a reference to internal mutable state, such as a private list, map or array, that the caller could modify?", .judgement = "The caller can modify internal state through the returned reference", .asks = .function },
    .{ .name = "cwe-378", .alias = "CWE-378", .advice = "Use a secure temporary file API that creates it atomically with private permissions.", .severity = .@"error", .tier = .default, .question = "Does the function create a temporary file with a predictable name or with permissions that let other users read or write it?", .judgement = "The temporary file is predictable or readable by others", .asks = .function },
    .{ .name = "cwe-379", .alias = "CWE-379", .advice = "Create it in a private directory, or with a secure temporary file API.", .severity = .warning, .tier = .default, .question = "Does the function create a temporary file in a shared or world-writable directory where other users can see or tamper with it?", .judgement = "The temporary file sits in a directory other users can access", .asks = .function },
    .{ .name = "cwe-385", .alias = "CWE-385", .advice = "Make timing independent of secret data.", .severity = .information, .tier = .default, .question = "Does the function let secret information influence the timing of observable behaviour, such as when messages are sent or how long operations take, so it could be inferred by watching?", .judgement = "Secret information affects observable timing", .asks = .function },
    .{ .name = "cwe-386", .alias = "CWE-386", .advice = "Look it up once and keep the handle.", .severity = .warning, .tier = .default, .question = "Does the function look up the same object by name or path more than once, such as checking a file by path and then opening it by path again, where the name could refer to a different object between the lookups?", .judgement = "The same name is looked up twice and could refer to different objects", .asks = .function },
    .{ .name = "cwe-392", .alias = "CWE-392", .advice = "Return an error or raise an exception when it fails.", .severity = .warning, .tier = .default, .question = "Does the function encounter an error but return normally, without an error code, exception or other signal that it failed?", .judgement = "The function fails without telling its caller", .asks = .function },
    .{ .name = "cwe-393", .alias = "CWE-393", .advice = "Return the status that reflects the real outcome.", .severity = .warning, .tier = .default, .question = "Does the function return a status code or value that does not reflect what actually happened, such as success after a failure or a generic error for a specific one?", .judgement = "The returned status does not match what happened", .asks = .function },
    .{ .name = "cwe-394", .alias = "CWE-394", .advice = "Handle every value the called function can return.", .severity = .warning, .tier = .default, .question = "Does the function call something that can return valid but unexpected values, such as zero, empty, partial or none, without handling those values?", .judgement = "A valid but unexpected return value is not handled", .asks = .function },
    .{ .name = "cwe-403", .alias = "CWE-403", .advice = "Mark them close-on-exec, or close them before starting the child.", .severity = .warning, .tier = .default, .question = "Does the function start a child process while sensitive file descriptors or handles, such as sockets, key files or database connections, are open and inheritable?", .judgement = "The child process inherits sensitive open handles", .asks = .function },
    .{ .name = "cwe-408", .alias = "CWE-408", .advice = "Authenticate and authorise first.", .severity = .warning, .tier = .default, .question = "Does the function perform expensive work, such as heavy computation, large allocations, database queries or outbound calls, before authenticating or authorising the caller?", .judgement = "Expensive work runs before the caller is authenticated", .asks = .function },
    .{ .name = "cwe-409", .alias = "CWE-409", .advice = "Cap the output size and ratio while decompressing.", .severity = .@"error", .tier = .default, .question = "Does the function decompress or expand input, such as zip, gzip, XML entities or images, without limiting the output size or compression ratio?", .judgement = "Decompressing input has no size limit, so a small bomb can exhaust memory or disk", .asks = .function },
    .{ .name = "cwe-410", .alias = "CWE-410", .advice = "Size it for peak demand, and limit how much one caller can take.", .severity = .information, .tier = .default, .question = "Does the function use a resource pool, such as connections, threads or workers, sized so that a burst of requests could exhaust it and block other users?", .judgement = "The resource pool can be exhausted by a burst of requests", .asks = .function },
    .{ .name = "cwe-412", .alias = "CWE-412", .advice = "Use a lock in a location only this program can access.", .severity = .warning, .tier = .default, .question = "Does the function rely on a lock, such as a lock file or named mutex, that other users or processes outside its control can create or hold?", .judgement = "An outside actor can take this lock and block the program", .asks = .function },
    .{ .name = "cwe-413", .alias = "CWE-413", .advice = "Lock it for the whole operation.", .severity = .@"error", .tier = .default, .question = "Does the function need exclusive access to a shared resource, such as a file, record or shared memory, but not lock it, or lock it incorrectly?", .judgement = "A shared resource is used without the exclusive lock it needs", .asks = .function },
    .{ .name = "cwe-414", .alias = "CWE-414", .advice = "Acquire or check the lock first.", .severity = .warning, .tier = .default, .question = "Does the function perform a sensitive operation on a shared resource without checking whether another process or thread holds its lock?", .judgement = "The lock is not checked before a sensitive operation", .asks = .function },
    .{ .name = "cwe-419", .alias = "CWE-419", .advice = "Protect it with authentication and encryption.", .severity = .@"error", .tier = .default, .question = "Does the function expose administrative or restricted functionality on a channel, such as an admin endpoint or management port, without authentication or encryption?", .judgement = "Restricted functionality is reachable on an unprotected channel", .asks = .function },
    .{ .name = "cwe-420", .alias = "CWE-420", .advice = "Apply the same authentication and authorisation checks to every path.", .severity = .@"error", .tier = .default, .question = "Does the function provide an alternate way to reach functionality, such as a debug endpoint, backup API or internal route, with weaker protection than the main path?", .judgement = "An alternate path has weaker protection than the main one", .asks = .function },
    .{ .name = "cwe-421", .alias = "CWE-421", .advice = "Authenticate the connection on the channel.", .severity = .warning, .tier = .default, .question = "Does the function open a secondary channel, such as a callback port, temporary socket or file, for an authorised user, where another actor could reach it first?", .judgement = "Another actor can reach this secondary channel before the intended user", .asks = .function },
    .{ .name = "cwe-425", .alias = "CWE-425", .advice = "Check authorisation on every request for it.", .severity = .@"error", .tier = .default, .question = "Does the function serve a restricted page, file or endpoint without checking that the requester is authorised, relying on the URL being unlinked or hard to guess?", .judgement = "A restricted resource is served without an authorisation check", .asks = .function },
    .{ .name = "cwe-428", .alias = "CWE-428", .advice = "Quote the path, or pass it as a separate argument.", .severity = .warning, .tier = .default, .question = "Does the function build or use a path to an executable containing spaces without quoting it, so it could run a program from a parent directory?", .judgement = "An unquoted path with spaces can run the wrong program", .asks = .function },
    .{ .name = "cwe-430", .alias = "CWE-430", .advice = "Choose it from verified type information.", .severity = .warning, .tier = .default, .question = "Does the function dispatch an object or request to a handler chosen by an untrusted attribute, such as a guessed file type or extension, that could select the wrong handler?", .judgement = "The handler is chosen from untrusted information and can be the wrong one", .asks = .function },
    .{ .name = "cwe-431", .alias = "CWE-431", .advice = "Add a handler, even if it only fails safely.", .severity = .warning, .tier = .default, .question = "Outside tests, does the function lack a handler for an event, message type, exception or enum value that it can evidently receive, such as a dispatch with no default branch?", .judgement = "A case, event or exception that can occur has no handler", .asks = .function },
    .{ .name = "cwe-434", .alias = "CWE-434", .advice = "Allow only safe types, check the content, and store uploads outside executable locations.", .severity = .@"error", .tier = .default, .question = "Does the function accept an uploaded file without restricting its type, extension and content, and store it where it could be served or executed?", .judgement = "Uploaded files of any type are accepted and could be executed", .asks = .function },
    .{ .name = "cwe-437", .alias = "CWE-437", .advice = "Parse exactly as the endpoint does, or normalise before forwarding.", .severity = .warning, .tier = .default, .question = "Does the function act as a proxy, filter or monitor between two systems but interpret requests or data differently from how the endpoint will, for example parsing headers or paths in another way?", .judgement = "This intermediary can interpret data differently from the endpoint", .asks = .function },
    .{ .name = "cwe-439", .alias = "CWE-439", .advice = "Use the documented API, or pin and check the version.", .severity = .information, .tier = .default, .question = "Does the function rely on a private, undocumented or experimental API of a library or platform, such as names starting with an underscore, or on behaviour documented to change between versions, without pinning or checking the version?", .judgement = "This relies on behaviour that may change between versions", .asks = .function },
    .{ .name = "cwe-440", .alias = "CWE-440", .advice = "Fix the behaviour or correct the specification.", .severity = .warning, .tier = .default, .question = "Does the function behave differently from its specification, documentation or the contract its name and signature imply?", .judgement = "The function does not behave as specified", .asks = .function },
    .{ .name = "cwe-444", .alias = "CWE-444", .advice = "Reject messages with conflicting or duplicated length headers.", .severity = .@"error", .tier = .default, .question = "Does the function forward or parse HTTP requests or responses, as a proxy, gateway or server, in a way that could interpret ambiguous framing, such as both Content-Length and Transfer-Encoding or duplicated headers, differently from the next hop?", .judgement = "Ambiguous HTTP framing could be read differently here and downstream, allowing request smuggling", .asks = .function },
    .{ .name = "cwe-447", .alias = "CWE-447", .advice = "Implement it, or remove it from the interface.", .severity = .warning, .tier = .default, .question = "Does the function present or report a security feature as enabled or working, such as a setting toggle or confirmation, when the underlying behaviour is not implemented?", .judgement = "A security feature appears to work but does nothing", .asks = .function },
    .{ .name = "cwe-448", .alias = "CWE-448", .advice = "Remove it, or warn the user it no longer works.", .severity = .information, .tier = .default, .question = "Does the function keep offering a feature or option that is obsolete or no longer has effect, without warning the user?", .judgement = "An obsolete feature is offered without warning", .asks = .function },
    .{ .name = "cwe-449", .alias = "CWE-449", .advice = "Make the action match the request.", .severity = .warning, .tier = .default, .question = "Does the function perform a different action from the one the user requested, such as acting on the wrong item or applying the wrong operation?", .judgement = "The action performed differs from what the user asked for", .asks = .function },
    .{ .name = "cwe-454", .alias = "CWE-454", .advice = "Initialise it from trusted sources, and validate anything external.", .severity = .@"error", .tier = .default, .question = "Does the function initialise security-critical internal state, such as a trusted identity, permissions, executable search path or security policy, from input controlled by a less trusted caller without validating that the caller may set it? Identify both the less trusted source and the security decision the initialised state controls. Ignore ordinary parsing, buffers, counters, result selection, and settings supplied by the person running the program or their editor, including workspace roots, environment variables, command-line arguments and configuration files.", .judgement = "Critical internal state is initialised from untrusted input", .asks = .function },
    .{ .name = "cwe-455", .alias = "CWE-455", .advice = "Stop, or refuse to serve, when security initialisation fails.", .severity = .@"error", .tier = .default, .question = "Does the function continue running after a security-relevant initialisation step fails, such as loading configuration, keys, certificates or a security module, possibly in a less secure mode?", .judgement = "Startup continues after a security setup step fails", .asks = .function },
    .{ .name = "cwe-459", .alias = "CWE-459", .advice = "Remove them in a finally block, a context manager or equivalent.", .severity = .warning, .tier = .default, .question = "Does the function create temporary or supporting resources, such as files, directories, processes or records, and fail to remove them on every path, including errors?", .judgement = "Temporary resources are not cleaned up on every path", .asks = .function },
    .{ .name = "cwe-472", .alias = "CWE-472", .advice = "Look it up or recompute it on the server.", .severity = .@"error", .tier = .default, .question = "Does the function trust a value from the client that is assumed not to change, such as a hidden form field, price, user ID or role in a request, without checking it on the server?", .judgement = "A value the client can change is trusted as fixed", .asks = .function },
    .{ .name = "cwe-474", .alias = "CWE-474", .advice = "Use a portable alternative, or handle each behaviour.", .severity = .information, .tier = .default, .question = "Does the function call a function whose behaviour differs across operating systems, platforms or versions in ways the code depends on?", .judgement = "This relies on a function that behaves differently across platforms or versions", .asks = .function },
    .{ .name = "cwe-475", .alias = "CWE-475", .advice = "Pass only values the API documents as valid.", .severity = .warning, .tier = .default, .question = "Does the function call an API with an argument value for which the API's behaviour is undefined, such as overlapping buffers to memcpy or an invalid flag?", .judgement = "The API is called with arguments that give undefined behaviour", .asks = .function },
    .{ .name = "cwe-476", .alias = "CWE-476", .advice = "Check it and handle the null case.", .severity = .@"error", .tier = .default, .question = "Does the function dereference a pointer, reference or optional value that can be null, None or nil, such as a lookup or allocation result, without checking it first?", .judgement = "A value that can be null is used without checking", .asks = .function },
    .{ .name = "cwe-487", .alias = "CWE-487", .advice = "Make sensitive members private and check permissions explicitly.", .severity = .warning, .tier = .default, .question = "Does this Java file rely on package-private or default visibility to protect sensitive fields or methods from other code?", .judgement = "Package visibility is not a security boundary", .asks = .file },
    .{ .name = "cwe-488", .alias = "CWE-488", .advice = "Keep it in request or session scope.", .severity = .@"error", .tier = .default, .question = "Does the function store request- or session-specific data in shared state, such as a singleton, static field, global or cached object, where another session could see or use it?", .judgement = "Data for one session is kept where another session can reach it", .asks = .function },
    .{ .name = "cwe-497", .alias = "CWE-497", .advice = "Remove them from responses and error pages.", .severity = .warning, .tier = .default, .question = "Does the function expose system details, such as versions, paths, hostnames, environment variables or internal addresses, to users or callers who should not see them?", .judgement = "System details are exposed to people who should not see them", .asks = .function },
    .{ .name = "cwe-501", .alias = "CWE-501", .advice = "Validate it before storing it alongside trusted data.", .severity = .warning, .tier = .default, .question = "Does the function put untrusted input into a data structure, session or message that the rest of the code treats as trusted, without validating it first?", .judgement = "Untrusted data is mixed into a trusted structure", .asks = .function },
    .{ .name = "cwe-515", .alias = "CWE-515", .advice = "Remove the side effect, or make it independent of secret data.", .severity = .information, .tier = .default, .question = "Does the function encode information in storage side effects, such as file attributes, flags or unused fields, where another program could read it covertly?", .judgement = "Information may leak through a covert storage channel", .asks = .function },
    .{ .name = "cwe-524", .alias = "CWE-524", .advice = "Do not cache it, or mark responses private and no-store.", .severity = .warning, .tier = .default, .question = "Does the function put sensitive information into a cache, such as a shared, HTTP, CDN or on-disk cache, that others outside the intended audience could read?", .judgement = "Sensitive data is cached where others can read it", .asks = .function },
    .{ .name = "cwe-538", .alias = "CWE-538", .advice = "Write it to a private location with restricted permissions.", .severity = .@"error", .tier = .default, .question = "Does the function write sensitive information, such as secrets, credentials or personal data, into files or directories that are accessible to users who should not see it, such as public web roots or shared folders?", .judgement = "Sensitive data is written where others can read it", .asks = .function },
    .{ .name = "cwe-544", .alias = "CWE-544", .advice = "Use the project's standard error handling mechanism.", .severity = .information, .tier = .default, .question = "Does the function handle errors in its own ad hoc way, such as custom codes, printing or swallowing, instead of the standard error mechanism the rest of the codebase uses?", .judgement = "Errors are handled differently from the rest of the codebase", .asks = .function },
    .{ .name = "cwe-549", .alias = "CWE-549", .advice = "Mask it, for example with a password field or getpass.", .severity = .warning, .tier = .default, .question = "Does the function display, echo or accept a password in a visible field, prompt or output instead of masking it?", .judgement = "A password is shown on screen while being entered", .asks = .function },
    .{ .name = "cwe-551", .alias = "CWE-551", .advice = "Decode and normalise first, then authorise.", .severity = .@"error", .tier = .default, .question = "Does the function make an authorisation decision on a URL, path or request before fully decoding and canonicalising it?", .judgement = "Authorisation checks the request before it is canonicalised, so encoded forms can bypass it", .asks = .function },
    .{ .name = "cwe-563", .alias = "CWE-563", .advice = "Remove the assignment, or use the value if it was meant to be used.", .severity = .information, .tier = .default, .question = "Does the function assign a value to a named variable that is never read before being overwritten or going out of scope? Ignore assignments to _ or other names used to discard a value on purpose.", .judgement = "A value is assigned and never used", .asks = .function },
    .{ .name = "cwe-565", .alias = "CWE-565", .advice = "Sign the cookie and verify it, or keep the value on the server.", .severity = .@"error", .tier = .default, .question = "Does the function rely on a cookie's presence or value for a security decision, such as authentication, role or price, without validating or signing it?", .judgement = "A security decision trusts a cookie the client can change", .asks = .function },
    .{ .name = "cwe-587", .alias = "CWE-587", .advice = "Obtain the address from the platform or an allocation.", .severity = .@"error", .tier = .default, .question = "Does the function assign a fixed numeric address, other than null, to a pointer?", .judgement = "A pointer is set to a fixed address that will not be valid everywhere", .asks = .function },
    .{ .name = "cwe-603", .alias = "CWE-603", .advice = "Check it on the server.", .severity = .@"error", .tier = .default, .question = "Does the function rely on authentication or authorisation checks performed in client-side code, without the server checking again?", .judgement = "Authentication happens only in the client, which a modified client can skip", .asks = .function },
    .{ .name = "cwe-605", .alias = "CWE-605", .advice = "Avoid port-sharing options, or use exclusive binding.", .severity = .warning, .tier = .default, .question = "Does the function bind a socket with options, such as SO_REUSEADDR or SO_REUSEPORT, that let another process bind the same port and steal or spoof traffic?", .judgement = "Another process can bind the same port and intercept traffic", .asks = .function },
    .{ .name = "cwe-606", .alias = "CWE-606", .advice = "Cap the loop bound to a sensible maximum.", .severity = .@"error", .tier = .default, .question = "Does the function use untrusted input (a request, upload, message or another user, not the program's own arguments or configuration) as a loop bound or iteration count without limiting it?", .judgement = "Input controls how many times this loop runs", .asks = .function },
    .{ .name = "cwe-609", .alias = "CWE-609", .advice = "Make the field volatile, or use a safe lazy initialiser.", .severity = .@"error", .tier = .default, .question = "Does the function use double-checked locking, checking a field outside a lock and again inside, without the field being volatile or atomic?", .judgement = "Double-checked locking without a volatile or atomic field can see a half-built object", .asks = .function },
    .{ .name = "cwe-617", .alias = "CWE-617", .advice = "Raise a specific error and report it clearly instead.", .severity = .warning, .tier = .default, .question = "Can a caller provide a concrete invalid external input that reaches an assert, panic or abort instead of a handled input error? Identify the input and the assertion it reaches. Ignore assertions of internal API contracts, buffer bookkeeping, parser cursor invariants or postconditions unless the shown control flow demonstrates that ordinary invalid external input can violate them. A function parameter alone is not evidence of an untrusted source.", .judgement = "Bad input from outside the program is rejected with an assertion, which crashes with a traceback and disappears when assertions are disabled", .asks = .function },
    .{ .name = "cwe-618", .alias = "CWE-618", .advice = "Remove the method, or restrict it to trusted origins.", .severity = .@"error", .tier = .default, .question = "Does the function expose methods to web page scripts, such as through ActiveX, a browser plugin, a webview bridge or a scripting interface, that can perform actions outside the browser sandbox?", .judgement = "Web content can call a dangerous method outside the sandbox", .asks = .function },
    .{ .name = "cwe-619", .alias = "CWE-619", .advice = "Close it in a finally block or context manager.", .severity = .warning, .tier = .default, .question = "Does the function open a database cursor or result set without closing it on every path, including errors?", .judgement = "A database cursor can be left open", .asks = .function },
    .{ .name = "cwe-620", .alias = "CWE-620", .advice = "Require the current password or another proof of identity.", .severity = .@"error", .tier = .default, .question = "Does the function change a user's password without requiring the current password or another re-authentication?", .judgement = "The password can be changed without re-authenticating", .asks = .function },
    .{ .name = "cwe-628", .alias = "CWE-628", .advice = "Check each argument's order, value and meaning against the called function.", .severity = .@"error", .tier = .default, .question = "Does the function call another function with arguments that are wrong, such as in the wrong order, the wrong variable, a wrong count or the wrong type or unit?", .judgement = "A call passes the wrong arguments", .asks = .function },
    .{ .name = "cwe-639", .alias = "CWE-639", .advice = "Check the record belongs to or is allowed for the caller.", .severity = .@"error", .tier = .default, .question = "Does the function fetch, update or delete a record identified by a key from the request, such as an ID in the URL or body, without checking the record belongs to or is permitted for the caller?", .judgement = "Changing the ID in the request reaches another user's data", .asks = .function },
    .{ .name = "cwe-640", .alias = "CWE-640", .advice = "Send a single-use, short-lived, random reset link to a verified address.", .severity = .@"error", .tier = .default, .question = "Does the function implement password recovery in a weak way, such as security questions, predictable or long-lived reset tokens, or sending the password itself?", .judgement = "Password recovery is weak", .asks = .function },
    .{ .name = "cwe-641", .alias = "CWE-641", .advice = "Allow only safe characters and a bounded length.", .severity = .warning, .tier = .default, .question = "Does the function build a file or resource name from input without restricting its length or characters, so the name could contain scripting, separators or reserved names?", .judgement = "A resource name built from input is not restricted", .asks = .function },
    .{ .name = "cwe-645", .alias = "CWE-645", .advice = "Use increasing delays or temporary lockouts instead.", .severity = .information, .tier = .default, .question = "Does the function lock accounts so easily, such as after very few failures or permanently, that an attacker could deliberately lock out legitimate users?", .judgement = "The lockout is easy to trigger against other users", .asks = .function },
    .{ .name = "cwe-648", .alias = "CWE-648", .advice = "Follow the API's requirements for privilege and argument checks.", .severity = .@"error", .tier = .default, .question = "Does the function call a privileged API incorrectly, such as without the required checks, in the wrong order or with unvalidated arguments?", .judgement = "A privileged API is used incorrectly", .asks = .function },
    .{ .name = "cwe-649", .alias = "CWE-649", .advice = "Add a MAC or use authenticated encryption.", .severity = .@"error", .tier = .default, .question = "Does the function rely on encrypting or obfuscating a value sent to the client, such as a token or hidden field, without an integrity check to detect tampering?", .judgement = "Encrypted or obfuscated client data can be tampered with undetected", .asks = .function },
    .{ .name = "cwe-653", .alias = "CWE-653", .advice = "Separate privileged work into its own component with its own checks.", .severity = .warning, .tier = .default, .question = "Does the function mix operations that need different privilege levels in one place, without separating or isolating them?", .judgement = "Operations needing different privileges are not isolated", .asks = .function },
    .{ .name = "cwe-654", .alias = "CWE-654", .advice = "Combine independent checks for this decision.", .severity = .warning, .tier = .default, .question = "Does the function make an access decision based on a single condition that could be spoofed or wrong, such as one header, flag or IP address?", .judgement = "Access depends on a single condition", .asks = .function },
    .{ .name = "cwe-656", .alias = "CWE-656", .advice = "Use real authentication, authorisation or cryptography.", .severity = .warning, .tier = .default, .question = "Does the function rely on secrecy of its algorithm, hidden URLs, obfuscation or undocumented parameters as the main security protection?", .judgement = "Security relies on obscurity", .asks = .function },
    .{ .name = "cwe-663", .alias = "CWE-663", .advice = "Use the reentrant variant, such as strtok_r.", .severity = .warning, .tier = .default, .question = "Does the function call a non-reentrant function, such as strtok, localtime or rand, from threads or signal handlers where another call could interleave?", .judgement = "A non-reentrant function is used where calls can interleave", .asks = .function },
    .{ .name = "cwe-681", .alias = "CWE-681", .advice = "Check the value fits in the target type first.", .severity = .@"error", .tier = .default, .question = "Does the function convert between numeric types, such as long to int, float to int, or signed to unsigned, in a way that can truncate, overflow or change sign?", .judgement = "This numeric conversion can lose data or change sign", .asks = .function },
    .{ .name = "cwe-694", .alias = "CWE-694", .advice = "Use a unique identifier, or reject duplicates.", .severity = .warning, .tier = .default, .question = "Does the function look up or operate on resources by an identifier that might not be unique, such as a name or non-unique field, where a unique identifier is required?", .judgement = "The identifier may match more than one resource", .asks = .function },
    .{ .name = "cwe-695", .alias = "CWE-695", .advice = "Use the framework's supported API.", .severity = .warning, .tier = .default, .question = "Does the function use low-level functionality that the framework or platform forbids, such as raw sockets, threads or file access inside a managed container, bypassing its protections?", .judgement = "This bypasses the framework using forbidden low-level calls", .asks = .function },
    .{ .name = "cwe-698", .alias = "CWE-698", .advice = "Return or exit immediately after redirecting.", .severity = .@"error", .tier = .default, .question = "Does the function send or return a redirect but then keep executing code that should not run, such as a missing return after redirect?", .judgement = "Code keeps running after the redirect", .asks = .function },
    .{ .name = "cwe-708", .alias = "CWE-708", .advice = "Assign ownership to the intended user or process.", .severity = .warning, .tier = .default, .question = "Does the function assign ownership of a resource, such as a file, record or object, to a user or process that should not own it?", .judgement = "A resource is given to the wrong owner", .asks = .function },
    .{ .name = "cwe-733", .alias = "CWE-733", .advice = "Use explicit_bzero, a volatile write or another optimisation-safe primitive.", .severity = .warning, .tier = .default, .question = "Does the function include security-critical code that a compiler may optimise away, such as clearing a secret with memset before free, or a check on undefined behaviour?", .judgement = "The compiler may remove this security-critical code", .asks = .function },
    .{ .name = "cwe-749", .alias = "CWE-749", .advice = "Remove it, or require authorisation to call it.", .severity = .@"error", .tier = .default, .question = "Does the function expose a dangerous capability, such as running commands, reading files or evaluating code, to callers less trusted than the program itself, such as web requests, remote clients, plugins or other users, without restricting who can call it? Ignore a program, script or command-line tool that does these things itself for the person running it.", .judgement = "A dangerous operation is exposed without restriction", .asks = .function },
    .{ .name = "cwe-756", .alias = "CWE-756", .advice = "Return a custom error response.", .severity = .warning, .tier = .default, .question = "Does the function let the framework's default error page or raw exception output reach the user instead of a custom error response?", .judgement = "Default error pages can expose internal details", .asks = .function },
    .{ .name = "cwe-764", .alias = "CWE-764", .advice = "Take each lock once per critical section, or use a reentrant lock deliberately.", .severity = .@"error", .tier = .default, .question = "Does the function acquire the same lock more times than intended, for example locking a non-recursive mutex twice, which could deadlock?", .judgement = "A lock can be taken twice", .asks = .function },
    .{ .name = "cwe-765", .alias = "CWE-765", .advice = "Release it exactly once, for example with a scoped guard.", .severity = .@"error", .tier = .default, .question = "Does the function release a lock more times than it acquired it, for example unlocking on several paths?", .judgement = "A lock can be released twice", .asks = .function },
    .{ .name = "cwe-766", .alias = "CWE-766", .advice = "Make it private and control access through methods.", .severity = .warning, .tier = .default, .question = "Does this file declare a critical field of a class, such as a password, key, balance or permission, as public?", .judgement = "A critical field is public", .asks = .file },
    .{ .name = "cwe-767", .alias = "CWE-767", .advice = "Validate and authorise access, or remove the method.", .severity = .warning, .tier = .default, .question = "Does the function provide public access that reads or modifies a critical private variable without validation or authorisation?", .judgement = "A public method exposes critical private state", .asks = .function },
    .{ .name = "cwe-771", .alias = "CWE-771", .advice = "Keep a reference and release it when done.", .severity = .warning, .tier = .default, .question = "Does the function allocate a resource and then lose every reference to it, so it can never be released?", .judgement = "A resource is allocated and then lost, so it cannot be released", .asks = .function },
    .{ .name = "cwe-772", .alias = "CWE-772", .advice = "Release it in a finally block, a context manager, defer or RAII.", .severity = .warning, .tier = .default, .question = "Does the function acquire a resource, such as a file, socket, connection, lock, handle or memory, and not release it on every path once it is no longer needed, including when an error occurs?", .judgement = "A resource is not released on every path", .asks = .function },
    .{ .name = "cwe-778", .alias = "CWE-778", .advice = "Log the actor, action, target, outcome and time.", .severity = .warning, .tier = .default, .question = "Does the function handle a security-critical event, such as a login, failed authorisation, permission change or data export, without logging it or while omitting key details such as who, what and when?", .judgement = "A security-critical event is not logged, or is logged without key details", .asks = .function },
    .{ .name = "cwe-779", .alias = "CWE-779", .advice = "Log only the fields that help diagnose problems.", .severity = .information, .tier = .default, .question = "Does the function log far more data than needed, such as whole payloads, large objects or every iteration of a loop, making logs hard to use?", .judgement = "This logs much more than needed", .asks = .function },
    .{ .name = "cwe-791", .alias = "CWE-791", .advice = "Encode the output for its context, or filter every occurrence of every dangerous element.", .severity = .warning, .tier = .default, .question = "Does the function filter special characters or sequences from input before passing it on, but miss some of them, such as only the first occurrence or only some of the dangerous characters?", .judgement = "The filter misses some special elements", .asks = .function },
    .{ .name = "cwe-804", .alias = "CWE-804", .advice = "Use a proven CAPTCHA service, and keep the answer on the server.", .severity = .warning, .tier = .default, .question = "Does the function implement a CAPTCHA or human check that a program could easily guess or solve, such as a simple sum, a fixed set of answers or an answer exposed to the client?", .judgement = "The CAPTCHA can be solved automatically", .asks = .function },
    .{ .name = "cwe-807", .alias = "CWE-807", .advice = "Base the decision on server-side state or verified credentials.", .severity = .@"error", .tier = .default, .question = "Does the function make a security decision, such as authentication, authorisation or pricing, based on input an untrusted actor can change, such as a cookie, header, hidden field or environment variable?", .judgement = "A security decision trusts input the caller can change", .asks = .function },
    .{ .name = "cwe-820", .alias = "CWE-820", .advice = "Protect it with a lock or use a thread-safe structure.", .severity = .@"error", .tier = .default, .question = "Does the function use a resource shared between threads, processes or async tasks, such as a variable, file or collection, without any synchronisation?", .judgement = "A shared resource is used concurrently without synchronisation", .asks = .function },
    .{ .name = "cwe-821", .alias = "CWE-821", .advice = "Use one lock for every access, held for the whole operation.", .severity = .@"error", .tier = .default, .question = "Does the function synchronise access to a shared resource incorrectly, such as locking only some accesses, using different locks for the same data or releasing the lock too early?", .judgement = "Synchronisation here does not fully protect the shared resource", .asks = .function },
    .{ .name = "cwe-826", .alias = "CWE-826", .advice = "Release it only after every user is done, for example with reference counting or ownership.", .severity = .@"error", .tier = .default, .question = "Does the function release, close or free a resource that is still in use by itself or other code, such as closing a shared connection or freeing memory that is still referenced?", .judgement = "A resource is released while still in use", .asks = .function },
    .{ .name = "cwe-832", .alias = "CWE-832", .advice = "Unlock only on paths where it was acquired, for example with a scoped guard.", .severity = .@"error", .tier = .default, .question = "Does the function unlock a lock or release a resource that may not be locked or held by it on the current path?", .judgement = "A lock may be released when it is not held", .asks = .function },
    .{ .name = "cwe-833", .alias = "CWE-833", .advice = "Always take locks in one global order, and do not wait while holding a lock.", .severity = .@"error", .tier = .default, .question = "Does the function acquire two or more locks in an order that could differ from other code, or wait on something while holding a lock, so threads could deadlock?", .judgement = "Lock ordering here can deadlock", .asks = .function },
    .{ .name = "cwe-836", .alias = "CWE-836", .advice = "Receive the password over TLS and hash it on the server.", .severity = .@"error", .tier = .default, .question = "Does the function authenticate a user by comparing a password hash sent by the client with the stored hash, so the hash itself works as the password?", .judgement = "The stored hash works as a password", .asks = .function },
    .{ .name = "cwe-837", .alias = "CWE-837", .advice = "Record that it happened and check atomically before allowing it again.", .severity = .warning, .tier = .default, .question = "Does the function allow an action that should happen only once per user, such as voting, redeeming a code or claiming a reward, to be repeated?", .judgement = "An action meant to happen once can be repeated", .asks = .function },
    .{ .name = "cwe-841", .alias = "CWE-841", .advice = "Check the workflow state before each step.", .severity = .@"error", .tier = .default, .question = "Does the function allow a step of a multi-step workflow, such as checkout, reset or approval, to run without checking the previous steps were completed in order?", .judgement = "A workflow step can be run out of order or skipped", .asks = .function },
    .{ .name = "cwe-842", .alias = "CWE-842", .advice = "Assign groups from verified server-side policy.", .severity = .@"error", .tier = .default, .question = "Does the function add a user to a group or role other than the one intended, such as a default admin group or one chosen from the request?", .judgement = "The user is put in the wrong group", .asks = .function },
    .{ .name = "cwe-908", .alias = "CWE-908", .advice = "Initialise it on every path before use.", .severity = .@"error", .tier = .default, .question = "Does the function use a variable, field, buffer or resource before it has been initialised on every path?", .judgement = "Something may be used before it is initialised", .asks = .function },
    .{ .name = "cwe-909", .alias = "CWE-909", .advice = "Initialise every field when creating it.", .severity = .warning, .tier = .default, .question = "Does the function create a critical resource, such as a struct, object, buffer or configuration, without initialising all of its fields?", .judgement = "A critical resource is left partly uninitialised", .asks = .function },
    .{ .name = "cwe-910", .alias = "CWE-910", .advice = "Stop using it after close, and set it to an invalid value.", .severity = .@"error", .tier = .default, .question = "Does the function use a file descriptor or handle after it may have been closed?", .judgement = "A file descriptor may be used after it is closed", .asks = .function },
    .{ .name = "cwe-911", .alias = "CWE-911", .advice = "Balance each increment with one decrement on every path.", .severity = .@"error", .tier = .default, .question = "Does the function increment or decrement a reference count incorrectly, such as missing a decrement on an error path or decrementing twice?", .judgement = "The reference count can become wrong, leaking or freeing the resource early", .asks = .function },
    .{ .name = "cwe-914", .alias = "CWE-914", .advice = "Use an explicit map of allowed names.", .severity = .@"error", .tier = .default, .question = "Does the function read or write variables whose names come from input, for example through extract, globals, setattr, eval or dynamic variable names?", .judgement = "Input chooses which variables are read or written", .asks = .function },
    .{ .name = "cwe-920", .alias = "CWE-920", .advice = "Use events, backoff or sleep instead of polling or busy loops.", .severity = .information, .tier = .default, .question = "Does the function run continuous or repeated work, such as polling, busy loops or wake locks, that wastes power on battery-powered or constrained devices?", .judgement = "This keeps working in a way that drains power", .asks = .function },
    .{ .name = "cwe-921", .alias = "CWE-921", .advice = "Store it in private storage, or encrypt it.", .severity = .warning, .tier = .default, .question = "Does the function store sensitive data on storage without access control, such as external storage, removable media or shared directories?", .judgement = "Sensitive data is stored where any app or user can read it", .asks = .function },
    .{ .name = "cwe-924", .alias = "CWE-924", .advice = "Use TLS, or add a MAC or signature and verify it.", .severity = .@"error", .tier = .default, .question = "Does the function receive messages over a channel without verifying they were not modified in transit, for example no TLS, MAC or signature?", .judgement = "Messages are not protected against tampering in transit", .asks = .function },
    .{ .name = "cwe-939", .alias = "CWE-939", .advice = "Check the caller, and require confirmation for sensitive actions.", .severity = .@"error", .tier = .default, .question = "Does the function handle a custom URL scheme, deep link or intent without checking which app or caller invoked it before acting?", .judgement = "Any app can invoke this handler", .asks = .function },
    .{ .name = "cwe-940", .alias = "CWE-940", .advice = "Authenticate the peer before acting.", .severity = .@"error", .tier = .default, .question = "Does the function accept an incoming connection, message or request and act on it without verifying it comes from the expected source?", .judgement = "The source of the incoming channel is not verified", .asks = .function },
    .{ .name = "cwe-941", .alias = "CWE-941", .advice = "Use the configured destination and verify its identity.", .severity = .@"error", .tier = .default, .question = "Does the function send an outgoing request to a destination that is wrong or not verified, such as a destination from input, a misconfigured address or a host without checking its identity?", .judgement = "Outgoing requests may go to the wrong destination", .asks = .function },
    .{ .name = "cwe-1007", .alias = "CWE-1007", .advice = "Normalise the text, and flag mixed scripts or confusable characters.", .severity = .information, .tier = .default, .question = "Does the function display identifiers, such as usernames, domains or URLs, without distinguishing visually similar characters from different scripts?", .judgement = "Look-alike characters can make one identifier pass for another", .asks = .function },
    .{ .name = "cwe-1024", .alias = "CWE-1024", .advice = "Convert them to one type first, and use strict equality.", .severity = .warning, .tier = .default, .question = "Does the function compare values of incompatible types, such as a string with a number, or use loose equality that converts types implicitly?", .judgement = "Values of different types are compared, which can give wrong results", .asks = .function },
    .{ .name = "cwe-1025", .alias = "CWE-1025", .advice = "Compare the attributes that define identity or equality.", .severity = .warning, .tier = .default, .question = "Does the function compare the wrong attributes of two things, such as references instead of values, names instead of IDs, or only part of a key?", .judgement = "The comparison looks at the wrong properties", .asks = .function },
    .{ .name = "cwe-1037", .alias = "CWE-1037", .advice = "Add a speculation barrier or use a hardened primitive.", .severity = .information, .tier = .default, .question = "Does the function rely on execution order or timing for a security-critical check in a way a processor could change through speculative or out-of-order execution, for example a bounds check before an access that uses secret data?", .judgement = "Speculative execution can bypass this security check", .asks = .function },
    .{ .name = "cwe-1043", .alias = "CWE-1043", .advice = "Split it into smaller, focused structures.", .severity = .information, .tier = .default, .question = "Does this file define a data structure or class with more than five fields that are themselves structures, objects or collections?", .judgement = "A data structure here has too many non-primitive fields", .asks = .file },
    .{ .name = "cwe-1044", .alias = "CWE-1044", .advice = "Arrange calls through a clear, small set of layers.", .severity = .information, .tier = .default, .question = "Does the function reach across many architectural layers at once, such as a user interface handler calling storage, business logic and network layers directly, in a way that suggests too few or too many layers?", .judgement = "This function spans an unusual number of architectural layers", .asks = .function },
    .{ .name = "cwe-1046", .alias = "CWE-1046", .advice = "Collect the parts and join them once, or use a string builder.", .severity = .information, .tier = .default, .question = "Does the function build an immutable string by repeated concatenation in a loop, such as += on a string, instead of using a builder or join?", .judgement = "Concatenating strings in a loop copies them each time", .asks = .function },
    .{ .name = "cwe-1047", .alias = "CWE-1047", .advice = "Move the shared code into a module both can depend on.", .severity = .information, .tier = .default, .question = "Does this file import a module that evidently imports this file's own module back, directly or through deferred imports placed to avoid a cycle?", .judgement = "This file is part of a circular dependency", .asks = .file },
    .{ .name = "cwe-1048", .alias = "CWE-1048", .advice = "Split it, or hide the calls behind fewer collaborators.", .severity = .information, .tier = .default, .question = "Does the function call an excessively large number of distinct functions or objects outside its own module, for example more than five?", .judgement = "This function depends on too many outside functions", .asks = .function },
    .{ .name = "cwe-1049", .alias = "CWE-1049", .advice = "Simplify it, denormalise, or precompute the result.", .severity = .information, .tier = .default, .question = "Does the function run a query with many joins or subqueries, such as more than five, over large tables?", .judgement = "This query has many joins or subqueries on large tables", .asks = .function },
    .{ .name = "cwe-1050", .alias = "CWE-1050", .advice = "Acquire them once outside the loop, or reuse a pool.", .severity = .warning, .tier = .default, .question = "Does the function acquire costly platform resources, such as connections, sessions, locks, threads or file handles, inside a loop body or condition?", .judgement = "Platform resources are acquired in a loop", .asks = .function },
    .{ .name = "cwe-1051", .alias = "CWE-1051", .advice = "Read them from configuration.", .severity = .warning, .tier = .default, .question = "Does the function initialise data with hard coded network details, such as IP addresses, hostnames, ports or URLs?", .judgement = "Network locations are hard coded", .asks = .function },
    .{ .name = "cwe-1052", .alias = "CWE-1052", .advice = "Replace it with a named constant or configuration.", .severity = .information, .tier = .default, .question = "Outside tests, does the function initialise data with the same long literal, path, URL or magic number used elsewhere, or with one likely to change, instead of a named constant or configuration? Ignore messages, format strings, 0, 1 and empty values.", .judgement = "Data is initialised with an unnamed literal that is likely to change or is repeated", .asks = .function },
    .{ .name = "cwe-1053", .alias = "CWE-1053", .advice = "Add a module docstring or header comment explaining its purpose and how it fits in.", .severity = .information, .tier = .default, .question = "Is this file a module with complex or architecturally significant code but no module-level documentation of what it is for and how it fits into the design?", .judgement = "This module does not document its design", .asks = .file },
    .{ .name = "cwe-1054", .alias = "CWE-1054", .advice = "Go through the adjacent layer.", .severity = .information, .tier = .default, .question = "Does the function skip an architectural layer, such as a controller or handler calling the database or storage directly instead of going through the service or domain layer?", .judgement = "This skips a layer by calling a deeper layer directly", .asks = .function },
    .{ .name = "cwe-1055", .alias = "CWE-1055", .advice = "Inherit from one class and compose or use interfaces for the rest.", .severity = .information, .tier = .default, .question = "Does this file define a class that inherits from more than one concrete, non-abstract class?", .judgement = "A class inherits from more than one concrete class", .asks = .file },
    .{ .name = "cwe-1057", .alias = "CWE-1057", .advice = "Go through the data manager or repository instead.", .severity = .warning, .tier = .default, .question = "Does the function access the database or data store directly, such as with raw queries or connections, when the codebase evidently provides a central data manager, repository or ORM layer for that?", .judgement = "This bypasses the project's data access layer", .asks = .function },
    .{ .name = "cwe-1058", .alias = "CWE-1058", .advice = "Make it immutable, thread local or protected by a lock.", .severity = .@"error", .tier = .default, .question = "Does the function run in a multi-threaded context and modify a non-final static, global or shared member variable without synchronisation?", .judgement = "Shared mutable static state is modified from multiple threads", .asks = .function },
    .{ .name = "cwe-1060", .alias = "CWE-1060", .advice = "Combine them into one query or a batch.", .severity = .information, .tier = .default, .question = "Does the function make many separate database queries, such as more than five or one per item in a loop, where a single set-based query would do?", .judgement = "This makes many separate data queries", .asks = .function },
    .{ .name = "cwe-1062", .alias = "CWE-1062", .advice = "Move the behaviour into the child, or use an overridable method.", .severity = .warning, .tier = .default, .question = "Does this file define a parent class that refers to one of its own subclasses, their methods or members?", .judgement = "A parent class depends on its child class", .asks = .file },
    .{ .name = "cwe-1063", .alias = "CWE-1063", .advice = "Create them lazily, or pass them in where needed.", .severity = .information, .tier = .default, .question = "Does this file create class instances in a static initialiser block or at module import time, rather than when they are needed?", .judgement = "Instances are created in a static block or at import time", .asks = .file },
    .{ .name = "cwe-1065", .alias = "CWE-1065", .advice = "Use the server's managed resources API.", .severity = .warning, .tier = .default, .question = "Does the function manage low-level resources directly, such as threads, sockets or connections, inside a component meant to run on an application server that provides those resources?", .judgement = "Resources are managed directly instead of through the application server", .asks = .function },
    .{ .name = "cwe-1066", .alias = "CWE-1066", .advice = "Define an explicit serialisation method or version.", .severity = .information, .tier = .default, .question = "Does this file define a serialisable class that lacks an explicit serialisation method or version where the language expects one, such as serialVersionUID in Java?", .judgement = "A serialisable class has no serialisation control", .asks = .file },
    .{ .name = "cwe-1067", .alias = "CWE-1067", .advice = "Filter on indexed columns, or add an index.", .severity = .information, .tier = .default, .question = "Does the function run a query against a table in a way that cannot use an index, such as filtering on an unindexed column, a function of a column or a leading wildcard?", .judgement = "This query likely scans the whole table", .asks = .function },
    .{ .name = "cwe-1068", .alias = "CWE-1068", .advice = "Bring the code and documentation back into line.", .severity = .warning, .tier = .default, .question = "Does the function's implementation contradict its documented design, such as its docstring, spec reference or design comments?", .judgement = "The implementation differs from its documented design", .asks = .function },
    .{ .name = "cwe-1070", .alias = "CWE-1070", .advice = "Mark them transient, or replace them with serialisable data.", .severity = .warning, .tier = .default, .question = "Does this file define a serialisable class with fields that cannot be serialised, such as locks, sockets, file handles or connections?", .judgement = "A serialisable class holds fields that cannot be serialised", .asks = .file },
    .{ .name = "cwe-1072", .alias = "CWE-1072", .advice = "Use a connection pool or reuse one connection.", .severity = .information, .tier = .default, .question = "Does the function open a new connection to a database server for each request or operation, instead of reusing a pooled or long-lived connection?", .judgement = "A new database connection is opened for each operation", .asks = .function },
    .{ .name = "cwe-1073", .alias = "CWE-1073", .advice = "Use set-based queries, batching or eager loading.", .severity = .information, .tier = .default, .question = "Does the function send a large number of separate queries through a data manager or ORM, such as one per record, instead of using efficient set-based database operations?", .judgement = "This makes many separate data accesses", .asks = .function },
    .{ .name = "cwe-1074", .alias = "CWE-1074", .advice = "Flatten the hierarchy and prefer composition.", .severity = .information, .tier = .default, .question = "Does this file define a class with more than seven ancestor classes?", .judgement = "A class in this file has too deep an inheritance chain", .asks = .file },
    .{ .name = "cwe-1083", .alias = "CWE-1083", .advice = "Use the data manager component.", .severity = .warning, .tier = .default, .question = "Does the function read or write data through an ad hoc mechanism, such as files, raw sockets or direct SQL, when the codebase has a designated data manager component for that data?", .judgement = "Data is accessed outside the designated data manager", .asks = .function },
    .{ .name = "cwe-1084", .alias = "CWE-1084", .advice = "Split it, or batch the operations.", .severity = .information, .tier = .default, .question = "Does the function perform many file or data store operations, such as more than seven reads, writes or queries?", .judgement = "This function does many data or file operations", .asks = .function },
    .{ .name = "cwe-1085", .alias = "CWE-1085", .advice = "Delete it; version control keeps the history.", .severity = .information, .tier = .default, .question = "Does the function contain a large amount of commented-out code?", .judgement = "The function contains a lot of commented-out code", .asks = .function },
    .{ .name = "cwe-1086", .alias = "CWE-1086", .advice = "Reorganise the hierarchy or use composition.", .severity = .information, .tier = .default, .question = "Does this file define a class with more than ten direct subclasses?", .judgement = "A class in this file has too many direct subclasses", .asks = .file },
    .{ .name = "cwe-1089", .alias = "CWE-1089", .advice = "Keep only the indexes queries use.", .severity = .information, .tier = .default, .question = "Does the function create or define a large table with an excessive number of indexes, such as more than three?", .judgement = "This large table has too many indexes, slowing writes", .asks = .function },
    .{ .name = "cwe-1090", .alias = "CWE-1090", .advice = "Call a method on that class instead.", .severity = .information, .tier = .default, .question = "Does the function bypass an established encapsulation boundary by accessing another class's explicitly private implementation members instead of its provided interface? Identify the private member and the boundary being bypassed. Ignore ordinary public fields of structs, records, syntax nodes, configuration, buffers or data-transfer objects; a chain of field accesses alone is not an encapsulation violation.", .judgement = "This reaches into another class's internals", .asks = .function },
    .{ .name = "cwe-1092", .alias = "CWE-1092", .advice = "Give each layer its own entry point, or move it into a utility module.", .severity = .information, .tier = .default, .question = "Does the function evidently get used from several architectural layers, such as both the UI and the storage layer, while not being a general utility?", .judgement = "The same function is used across several layers", .asks = .function },
    .{ .name = "cwe-1094", .alias = "CWE-1094", .advice = "Narrow the range, paginate or add a more selective filter.", .severity = .information, .tier = .default, .question = "Does the function query a large table with an index range scan that could cover a very large number of rows, such as an unbounded date or ID range?", .judgement = "This query can scan a huge range of rows", .asks = .function },
    .{ .name = "cwe-1095", .alias = "CWE-1095", .advice = "Update the loop control in one place only.", .severity = .warning, .tier = .default, .question = "Does the function have a loop whose condition depends on a value that the loop body also modifies, such as changing the counter of a for loop inside the body or modifying the collection being iterated?", .judgement = "The loop body changes the value its condition depends on", .asks = .function },
    .{ .name = "cwe-1097", .alias = "CWE-1097", .advice = "Define equality, and hashing or ordering where needed.", .severity = .information, .tier = .default, .question = "Does this file define a class that is stored persistently or used as a key, such as an entity or record, without the equality, hashing or ordering methods needed to compare instances?", .judgement = "A stored class cannot be compared correctly", .asks = .file },
    .{ .name = "cwe-1099", .alias = "CWE-1099", .advice = "Use one convention and one name per concept.", .severity = .information, .tier = .default, .question = "Does this file name things inconsistently, such as mixing camelCase and snake_case for the same kind of name, or using different names for the same concept?", .judgement = "Names in this file follow inconsistent conventions", .asks = .file },
    .{ .name = "cwe-1100", .alias = "CWE-1100", .advice = "Move it behind one small platform module.", .severity = .information, .tier = .default, .question = "Does this file mix operating system or platform specific calls into general logic in several places, instead of isolating them in one module or function?", .judgement = "System-dependent code is scattered through this file", .asks = .file },
    .{ .name = "cwe-1101", .alias = "CWE-1101", .advice = "Document and pin the runtime, or generate code without that dependency.", .severity = .information, .tier = .default, .question = "Does the function rely on generated code that needs a specific runtime component or generator library to run?", .judgement = "This depends on generated code that needs a special runtime", .asks = .function },
    .{ .name = "cwe-1102", .alias = "CWE-1102", .advice = "Use fixed-size types and explicit byte order.", .severity = .warning, .tier = .default, .question = "Does the function depend on machine-specific data representation, such as byte order, word size, struct padding or the size of int or long?", .judgement = "This depends on how a particular machine represents data", .asks = .function },
    .{ .name = "cwe-1103", .alias = "CWE-1103", .advice = "Choose a portable component, or provide a fallback.", .severity = .information, .tier = .default, .question = "Does the function rely on a third-party component or API that only works on some of the platforms the code targets?", .judgement = "A third-party component used here is not available on every target platform", .asks = .function },
    .{ .name = "cwe-1104", .alias = "CWE-1104", .advice = "Replace it with a maintained alternative.", .severity = .warning, .tier = .default, .question = "Does the function use a third-party library or API that is evidently unmaintained, deprecated or abandoned?", .judgement = "This relies on an unmaintained third-party component", .asks = .function },
    .{ .name = "cwe-1105", .alias = "CWE-1105", .advice = "Put it behind a small interface.", .severity = .information, .tier = .default, .question = "Does this file use machine-dependent functionality, such as inline assembly, intrinsics or hardware registers, in several places without encapsulating it?", .judgement = "Machine-dependent code is not encapsulated in this file", .asks = .file },
    .{ .name = "cwe-1106", .alias = "CWE-1106", .advice = "Define a named constant for it.", .severity = .information, .tier = .default, .question = "Outside tests, does the function embed a literal limit, timeout, rate, size, threshold or retry count that is likely to change, or repeat the same literal in several places, without a named constant? Ignore messages, format strings, 0, 1 and empty values.", .judgement = "A value likely to change is a bare literal", .asks = .function },
    .{ .name = "cwe-1107", .alias = "CWE-1107", .advice = "Define each once, together, or in a shared constants module.", .severity = .information, .tier = .default, .question = "Does this file define the same constant more than once, or scatter constant definitions through its functions instead of grouping them in one place?", .judgement = "Constants in this file are duplicated or scattered", .asks = .file },
    .{ .name = "cwe-1108", .alias = "CWE-1108", .advice = "Pass state through parameters and return values.", .severity = .warning, .tier = .default, .question = "Does the function read or write global variables heavily instead of passing state through parameters and return values?", .judgement = "The function relies on global variables", .asks = .function },
    .{ .name = "cwe-1109", .alias = "CWE-1109", .advice = "Use a separate, well named variable for each.", .severity = .warning, .tier = .default, .question = "Does the function reuse one variable for more than one purpose, such as holding a count and later an unrelated value?", .judgement = "One variable is used for several purposes", .asks = .function },
    .{ .name = "cwe-1110", .alias = "CWE-1110", .advice = "Document its control flow, data flow and relationships.", .severity = .information, .tier = .default, .question = "Is the function complex, concurrent or part of initialisation, without documentation of its control flow, data flow or relationships to other components?", .judgement = "Important design aspects of this code are undocumented", .asks = .function },
    .{ .name = "cwe-1111", .alias = "CWE-1111", .advice = "Document each of them.", .severity = .information, .tier = .default, .question = "Does the function define an interface, such as a public API, CLI or endpoint, without documenting its inputs, outputs and errors?", .judgement = "This interface does not document its inputs, outputs or errors", .asks = .function },
    .{ .name = "cwe-1112", .alias = "CWE-1112", .advice = "Document each environment variable, option and key.", .severity = .information, .tier = .default, .question = "Does the function read environment variables, configuration keys, command-line options or registry keys that change how the program runs, without documenting them?", .judgement = "Settings that control execution are undocumented", .asks = .function },
    .{ .name = "cwe-1113", .alias = "CWE-1113", .advice = "Use one standard comment and docstring format.", .severity = .information, .tier = .default, .question = "Does this file use comment or docstring styles that are inconsistent with each other or with the language's standard format?", .judgement = "Comments in this file use inconsistent styles", .asks = .file },
    .{ .name = "cwe-1114", .alias = "CWE-1114", .advice = "Run the project formatter.", .severity = .information, .tier = .default, .question = "Does this file use inconsistent whitespace or indentation, such as mixed tabs and spaces or different indentation widths?", .judgement = "Whitespace in this file is inconsistent", .asks = .file },
    .{ .name = "cwe-1115", .alias = "CWE-1115", .advice = "Add the project's header, with its copyright or licence notice and what the module is for.", .severity = .information, .tier = .default, .question = "Does this file omit a header that the project demonstrably requires, such as a copyright or licence notice consistently present in comparable files? Identify the established header convention being violated. Do not assume every project requires per-file copyright notices or a particular header template; a missing module summary alone is not evidence of a missing required standard header.", .judgement = "This file has no standard header", .asks = .file },
    .{ .name = "cwe-1116", .alias = "CWE-1116", .advice = "Correct the comment, or the code if the comment is right.", .severity = .warning, .tier = .default, .question = "Does the function contain comments that do not accurately describe the code next to them?", .judgement = "A comment does not match the code", .asks = .function },
    .{ .name = "cwe-1117", .alias = "CWE-1117", .advice = "Document its inputs, return value, side effects and errors.", .severity = .information, .tier = .default, .question = "Is this a public function, not a test or a small private helper, whose inputs, return value, side effects or errors are neither evident from its name and signature nor documented?", .judgement = "The function's behaviour is not summarised", .asks = .function },
    .{ .name = "cwe-1118", .alias = "CWE-1118", .advice = "Document the errors it raises or returns and what they mean.", .severity = .information, .tier = .default, .question = "Does the function use an error handling technique, such as special return codes, error callbacks or custom exceptions, without documenting it?", .judgement = "How this code reports errors is undocumented", .asks = .function },
    .{ .name = "cwe-1119", .alias = "CWE-1119", .advice = "Restructure with loops, functions and early returns.", .severity = .warning, .tier = .default, .question = "Does the function use many unconditional branches, such as goto, or deeply scattered break and continue statements?", .judgement = "Too many unconditional jumps make control flow hard to follow", .asks = .function },
    .{ .name = "cwe-1122", .alias = "CWE-1122", .advice = "Break long expressions into named steps.", .severity = .information, .tier = .default, .question = "Is the function dense with many distinct operators and operands, making it hard to read, for example long expressions with many variables?", .judgement = "The function is dense with operators and operands", .asks = .function },
    .{ .name = "cwe-1123", .alias = "CWE-1123", .advice = "Use explicit configuration or dependency injection instead.", .severity = .warning, .tier = .default, .question = "Outside tests, does the function change code at runtime, such as monkey patching functions or classes of other modules, replacing methods on existing objects or writing executable memory?", .judgement = "Code is changed at runtime, which makes behaviour hard to predict", .asks = .function },
    .{ .name = "cwe-1125", .alias = "CWE-1125", .advice = "Remove or restrict the unnecessary ones.", .severity = .information, .tier = .default, .question = "Does the function add many externally reachable entry points, parameters or outputs, beyond what its purpose needs?", .judgement = "This exposes more entry points than needed", .asks = .function },
    .{ .name = "cwe-1127", .alias = "CWE-1127", .advice = "Turn on all warnings at the strictest level and treat them as errors.", .severity = .warning, .tier = .default, .question = "Do these build files compile the code without enabling the compiler's warnings at a strict level, or without treating warnings as errors?", .judgement = "The build does not enable strict compiler warnings", .asks = .project },
    .{ .name = "cwe-1173", .alias = "CWE-1173", .advice = "Validate through the framework for every field.", .severity = .warning, .tier = .default, .question = "Does the function validate input by hand, or bypass or misuse the validation framework the codebase uses, such as disabling validation or validating only some fields?", .judgement = "Input validation bypasses or misuses the validation framework", .asks = .function },
    .{ .name = "cwe-1220", .alias = "CWE-1220", .advice = "Check permission for each specific action and resource.", .severity = .warning, .tier = .default, .question = "Does the function apply access control too coarsely, such as one permission covering reads and writes or all records, where finer control is needed?", .judgement = "Access control is too coarse", .asks = .function },
    .{ .name = "cwe-1230", .alias = "CWE-1230", .advice = "Apply the same access control to its metadata.", .severity = .warning, .tier = .default, .question = "Does the function protect a sensitive resource but expose metadata derived from it, such as file sizes, timestamps, counts, names or search results?", .judgement = "Metadata reveals information about a protected resource", .asks = .function },
    .{ .name = "cwe-1235", .alias = "CWE-1235", .advice = "Use primitive types or primitive collections.", .severity = .information, .tier = .default, .question = "Does the function box numbers in a performance-critical loop or collection where primitives would do, such as Java's Integer or Double, or a C# int held as an object or in an ArrayList?", .judgement = "Boxing in hot code is slow", .asks = .function },
    .{ .name = "cwe-1236", .alias = "CWE-1236", .advice = "Prefix values that start with =, +, - or @ with a single quote.", .severity = .warning, .tier = .default, .question = "Does the function write untrusted input (a request, upload, message or another user, not the program's own arguments or configuration) into a CSV file without neutralising values starting with =, +, - or @ that a spreadsheet would run as a formula?", .judgement = "Values in this CSV can run as spreadsheet formulas", .asks = .function },
    .{ .name = "cwe-1240", .alias = "CWE-1240", .advice = "Use a vetted, standard cryptographic library.", .severity = .@"error", .tier = .default, .question = "Does the function implement its own cryptographic algorithm, or use a non-standard, unproven or disallowed implementation?", .judgement = "Cryptography is hand-rolled or non-standard", .asks = .function },
    .{ .name = "cwe-1241", .alias = "CWE-1241", .advice = "Use a cryptographically secure random generator.", .severity = .@"error", .tier = .default, .question = "Does the function generate random numbers with a predictable algorithm, such as a linear congruential generator or LFSR, where unpredictability is needed?", .judgement = "The random number algorithm is predictable", .asks = .function },
    .{ .name = "cwe-1265", .alias = "CWE-1265", .advice = "Guard against reentry, or defer the callback.", .severity = .warning, .tier = .default, .question = "Does the function call code that may, directly or through callbacks, call back into a non-reentrant function or object while it is already in progress?", .judgement = "A nested call can re-enter code that is not reentrant", .asks = .function },
    .{ .name = "cwe-1285", .alias = "CWE-1285", .advice = "Check it is at least zero and less than the size.", .severity = .@"error", .tier = .default, .question = "Does the function take an index, position or offset from input without checking it is within the bounds of the resource it indexes?", .judgement = "An index or offset from input is not checked against bounds", .asks = .function },
    .{ .name = "cwe-1286", .alias = "CWE-1286", .advice = "Parse it strictly and reject malformed values with a clear error.", .severity = .warning, .tier = .default, .question = "Does the function accept external input that must follow a syntax, such as an email address, date, URL or structured format from a request, message or file, without checking it is well formed?", .judgement = "External input is not checked for well-formed syntax", .asks = .function },
    .{ .name = "cwe-1287", .alias = "CWE-1287", .advice = "Check or parse it into the expected type and reject anything else.", .severity = .warning, .tier = .default, .question = "Does the function accept a value from external input, such as a JSON or YAML field from a request, message or file, and assume its type, such as a number, list or map, without checking it?", .judgement = "The type of an external value is assumed", .asks = .function },
    .{ .name = "cwe-1288", .alias = "CWE-1288", .advice = "Check they agree before using them.", .severity = .warning, .tier = .default, .question = "Does the function accept external input with several fields that must agree with each other, such as a length and its data, or a start before an end, without checking that they do?", .judgement = "Related fields in external input are not checked for consistency", .asks = .function },
    .{ .name = "cwe-1289", .alias = "CWE-1289", .advice = "Normalise it, then check it against the unsafe values.", .severity = .@"error", .tier = .default, .question = "Does the function take an identifier, path, host or reference from untrusted input (a request, upload, message or another user, not the program's own arguments or configuration) without rejecting values equivalent to unsafe ones, such as encoded .., alternate IP forms or localhost aliases?", .judgement = "Untrusted input equivalent to an unsafe value is not rejected", .asks = .function },
    .{ .name = "cwe-1322", .alias = "CWE-1322", .advice = "Use the async API, or run it in a thread or process pool.", .severity = .@"error", .tier = .default, .question = "Does the function perform blocking operations, such as synchronous I/O, sleep or CPU-heavy work, inside async code or an event loop?", .judgement = "Blocking work inside async code stalls the event loop", .asks = .function },
    .{ .name = "cwe-1327", .alias = "CWE-1327", .advice = "Bind to localhost or a specific interface unless public access is intended.", .severity = .warning, .tier = .default, .question = "Does the function bind a server or service to 0.0.0.0 or all interfaces where only local or specific access is intended?", .judgement = "The service listens on every interface", .asks = .function },
    .{ .name = "cwe-1335", .alias = "CWE-1335", .advice = "Check it is between zero and the type's width minus one.", .severity = .@"error", .tier = .default, .question = "Does the function shift an integer by an amount that could be negative or at least the number of bits in its type?", .judgement = "The shift amount can be negative or too large", .asks = .function },
    .{ .name = "cwe-1339", .alias = "CWE-1339", .advice = "Use a decimal type or integers in the smallest unit.", .severity = .@"error", .tier = .default, .question = "Does the function use floating point for values that need exact precision, such as money, or in a way that loses required accuracy?", .judgement = "Floating point loses the precision this value needs", .asks = .function },
    .{ .name = "cwe-1341", .alias = "CWE-1341", .advice = "Release it once, and clear the handle afterwards.", .severity = .@"error", .tier = .default, .question = "Does the function close, free or release the same resource or handle more than once without reopening it in between?", .judgement = "A resource can be released twice", .asks = .function },
    .{ .name = "cwe-77", .alias = "CWE-77", .advice = "Pass input as separate arguments, or escape it for that command language.", .severity = .@"error", .tier = .default, .question = "Does the function build a command for an interpreter, shell or other command processor from untrusted input (a request, upload, message or another user, not the program's own arguments or configuration) without neutralising special characters?", .judgement = "Input is written into a command without neutralising it", .asks = .function },
    .{ .name = "cwe-99", .alias = "CWE-99", .advice = "Map it to an allow list of resources.", .severity = .@"error", .tier = .default, .question = "Does the function use untrusted input (a request, upload, message or another user, not the program's own arguments or configuration) as the identifier of a resource, such as a file, port, socket, table or queue, without restricting it to allowed values?", .judgement = "Input chooses which resource is used", .asks = .function },
    .{ .name = "cwe-129", .alias = "CWE-129", .advice = "Check it is within the array bounds before use.", .severity = .@"error", .tier = .default, .question = "Does the function use untrusted input (a request, upload, message or another user, not the program's own arguments or configuration), or a value derived from it, as an array index without checking it is at least zero and less than the array length?", .judgement = "An index from input is not checked", .asks = .function },
    .{ .name = "cwe-197", .alias = "CWE-197", .advice = "Check the value fits before casting.", .severity = .@"error", .tier = .default, .question = "Does the function cast a value to a smaller numeric type, losing high-order bits, where the value can exceed the smaller type's range?", .judgement = "Casting to a smaller type can lose data", .asks = .function },
    .{ .name = "cwe-401", .alias = "CWE-401", .advice = "Free it on every path, or use automatic ownership such as RAII or smart pointers.", .severity = .@"error", .tier = .default, .question = "Does the function allocate memory that is not freed on every path once it is no longer needed, for example leaking on an error return?", .judgement = "Allocated memory can leak", .asks = .function },
    .{ .name = "cwe-404", .alias = "CWE-404", .advice = "Close it with the right call on every path.", .severity = .warning, .tier = .default, .question = "Does the function fail to shut down or release a resource correctly, such as not closing it, closing it with the wrong call or leaving it half released?", .judgement = "A resource is not released correctly", .asks = .function },
    .{ .name = "cwe-407", .alias = "CWE-407", .advice = "Use a more efficient algorithm or data structure, or limit input size.", .severity = .warning, .tier = .default, .question = "Does the function use an algorithm whose worst case is quadratic or worse on input size, such as nested loops over input or repeated linear searches, where input can be large?", .judgement = "The worst-case cost grows badly with input size", .asks = .function },
    .{ .name = "cwe-424", .alias = "CWE-424", .advice = "Apply the same checks to every path.", .severity = .@"error", .tier = .default, .question = "Does the function provide another path to restricted functionality or data, such as a different endpoint, method or parameter, that skips the protections on the main path?", .judgement = "An alternate path skips the protections on the main one", .asks = .function },
    .{ .name = "cwe-456", .alias = "CWE-456", .advice = "Initialise it when you declare it.", .severity = .warning, .tier = .default, .question = "Does the function declare a critical variable without initialising it, relying on whatever value it happens to have?", .judgement = "A critical variable is not initialised", .asks = .function },
    .{ .name = "cwe-457", .alias = "CWE-457", .advice = "Assign it on every path before reading it.", .severity = .@"error", .tier = .default, .question = "Does the function read a variable before it has been assigned on every path?", .judgement = "A variable can be read before it is assigned", .asks = .function },
    .{ .name = "cwe-543", .alias = "CWE-543", .advice = "Create it eagerly, or synchronise its creation.", .severity = .@"error", .tier = .default, .question = "Does the function lazily create a singleton instance in a multi-threaded context without synchronisation?", .judgement = "Two threads can create the singleton at once", .asks = .function },
    .{ .name = "cwe-564", .alias = "CWE-564", .advice = "Use named or positional parameters.", .severity = .@"error", .tier = .default, .question = "Does the function build a Hibernate, JPA, ORM or HQL query by concatenating untrusted input (a request, upload, message or another user, not the program's own arguments or configuration) into the query string?", .judgement = "Input is concatenated into an ORM query", .asks = .function },
    .{ .name = "cwe-567", .alias = "CWE-567", .advice = "Synchronise it, or keep the data per request.", .severity = .@"error", .tier = .default, .question = "Does the function read or modify shared static or instance data in a multi-threaded context, such as a servlet, controller or request handler, without synchronisation?", .judgement = "Shared data is accessed from several threads without synchronisation", .asks = .function },
    .{ .name = "cwe-652", .alias = "CWE-652", .advice = "Bind it as an external variable.", .severity = .@"error", .tier = .default, .question = "Does the function build an XQuery expression by inserting untrusted input (a request, upload, message or another user, not the program's own arguments or configuration) as text instead of binding it as an external variable?", .judgement = "Input is written into an XQuery expression", .asks = .function },
    .{ .name = "cwe-662", .alias = "CWE-662", .advice = "Use a lock, transaction or other synchronisation.", .severity = .@"error", .tier = .default, .question = "Does the function share a resource that needs exclusive access across threads, processes or services without synchronisation that guarantees one user at a time?", .judgement = "Exclusive access to a shared resource is not guaranteed", .asks = .function },
    .{ .name = "cwe-665", .alias = "CWE-665", .advice = "Initialise it fully with correct values before it is used.", .severity = .warning, .tier = .default, .question = "Does the function initialise a resource incorrectly or incompletely, such as missing fields, wrong defaults or initialising after first use?", .judgement = "A resource is not initialised correctly", .asks = .function },
    .{ .name = "cwe-667", .alias = "CWE-667", .advice = "Acquire before use and release on every path, for example with a scoped guard.", .severity = .@"error", .tier = .default, .question = "Does the function acquire or release a lock incorrectly, such as not releasing it on an error path, releasing the wrong lock or not acquiring it before use?", .judgement = "Lock handling is incorrect", .asks = .function },
    .{ .name = "cwe-672", .alias = "CWE-672", .advice = "Check it is still valid, or obtain a fresh one.", .severity = .@"error", .tier = .default, .question = "Does the function use a resource after it has expired, been released, closed or revoked, such as a closed connection, expired token or freed object?", .judgement = "A resource is used after it expired or was released", .asks = .function },
    .{ .name = "cwe-682", .alias = "CWE-682", .advice = "Check the formula and test it with known values.", .severity = .@"error", .tier = .default, .question = "Does the function perform a calculation that gives a wrong result for its evident purpose, such as the wrong formula, wrong operand or wrong rounding?", .judgement = "This calculation gives the wrong result", .asks = .function },
    .{ .name = "cwe-703", .alias = "CWE-703", .advice = "Handle it, or let it propagate as a clear error.", .severity = .warning, .tier = .default, .question = "Does the function perform an operation that commonly fails in normal use, such as reading a file, parsing input, a network call or a database query, and either handle some of its failures but miss another common one, or carry on as if it succeeded when it may have failed?", .judgement = "A common failure of this operation is missed or ignored", .asks = .function },
    .{ .name = "cwe-704", .alias = "CWE-704", .advice = "Check the type or range before converting.", .severity = .@"error", .tier = .default, .question = "Does the function convert or cast a value or object to another type incorrectly, such as an unchecked downcast or converting between incompatible representations?", .judgement = "A type conversion here is incorrect", .asks = .function },
    .{ .name = "cwe-732", .alias = "CWE-732", .advice = "Restrict it to the owner or required group.", .severity = .@"error", .tier = .default, .question = "Does the function set permissions on a security-critical resource, such as a key, config file, socket or directory, that let unintended users read or modify it?", .judgement = "A critical resource gets permissions that are too broad", .asks = .function },
    .{ .name = "cwe-758", .alias = "CWE-758", .advice = "Rewrite it to depend only on specified behaviour.", .severity = .warning, .tier = .default, .question = "Does the function rely on behaviour that is undefined, unspecified or implementation-defined, such as dict ordering in old runtimes, evaluation order, signed overflow or uninitialised memory?", .judgement = "The code relies on behaviour that is not guaranteed", .asks = .function },
    .{ .name = "cwe-775", .alias = "CWE-775", .advice = "Use with, try-with-resources, defer or RAII.", .severity = .warning, .tier = .default, .question = "Does the function open a file, socket or handle and not close it on every path once it is no longer needed?", .judgement = "A file or handle is not closed on every path", .asks = .function },
    .{ .name = "cwe-1042", .alias = "CWE-1042", .advice = "Make it an instance member, or make it constant.", .severity = .warning, .tier = .default, .question = "Does this file define a class with a static or class-level member that is mutable, in a class that is not a singleton?", .judgement = "A mutable static member makes every instance share state", .asks = .file },
    .{ .name = "cwe-1088", .alias = "CWE-1088", .advice = "Set an explicit timeout.", .severity = .warning, .tier = .default, .question = "Does the function make a synchronous call to a remote resource, such as HTTP, database, RPC or socket, with no timeout or an infinite one?", .judgement = "A remote call has no timeout and can hang forever", .asks = .function },
    .{ .name = "cwe-1091", .alias = "CWE-1091", .advice = "Call close or dispose, or use a scoped construct.", .severity = .warning, .tier = .default, .question = "Does the function use an object that needs explicit disposal, such as close or dispose, without calling it afterwards?", .judgement = "An object is not disposed after use", .asks = .function },
    .{ .name = "cwe-1096", .alias = "CWE-1096", .advice = "Synchronise it, or create the instance eagerly.", .severity = .@"error", .tier = .default, .question = "Does the function implement singleton creation without locking or synchronisation, so more than one instance could be created concurrently?", .judgement = "Singleton creation is not synchronised", .asks = .function },
    .{ .name = "ext-build-002", .alias = "EXT-BUILD-002", .advice = "Import or define it, or fix the spelling.", .severity = .@"error", .tier = .default, .question = "Does this file use a name, module or attribute that is neither defined in the file, imported by it, a parameter nor a builtin of its language, without a guarded fallback?", .judgement = "A name used here is never defined or imported", .asks = .file },
    .{ .name = "ext-build-003", .alias = "EXT-BUILD-003", .advice = "Convert and validate it explicitly, or fix the declared type.", .severity = .@"error", .tier = .default, .question = "Does the function pass, return or assign a value whose type contradicts a declared type, such as a string where an integer parameter is declared, without a validated conversion?", .judgement = "A value breaks the declared type contract", .asks = .function },
    .{ .name = "ext-domain-001", .alias = "EXT-DOMAIN-001", .advice = "Implement it, or document that the requirement excludes it.", .severity = .warning, .tier = .default, .question = "Does the function evidently omit a case its docstring, name or surrounding requirements say it must handle, such as a documented status, input kind or eligibility rule with no code path?", .judgement = "A required case has no code path", .asks = .function },
    .{ .name = "ext-domain-002", .alias = "EXT-DOMAIN-002", .advice = "Check it against reference calculations for the agreed formula.", .severity = .@"error", .tier = .default, .question = "Does the function compute a business value, such as a price, tax, interest, fee or total, with a formula, rate, rounding or date rule that contradicts the domain rule it evidently implements?", .judgement = "This business calculation disagrees with the domain rule it implements", .asks = .function },
    .{ .name = "ext-domain-003", .alias = "EXT-DOMAIN-003", .advice = "Check the current state permits the transition before changing it.", .severity = .@"error", .tier = .default, .question = "Does the function change the state of a domain entity, such as an order, payment or account, to a state that its prior state should not allow, such as shipping a cancelled order, without checking the transition is valid?", .judgement = "A state change is allowed that the business state machine forbids", .asks = .function },
    .{ .name = "ext-domain-004", .alias = "EXT-DOMAIN-004", .advice = "Convert to one unit, and name variables with their unit.", .severity = .@"error", .tier = .default, .question = "Does the function combine, compare or assign values with different units or dimensions, such as milliseconds and seconds, metres and feet or cents and dollars, without converting?", .judgement = "Values in different units are combined without converting", .asks = .function },
    .{ .name = "ext-distributed-001", .alias = "EXT-DISTRIBUTED-001", .advice = "Deduplicate with a stable request identity or idempotency key.", .severity = .@"error", .tier = .default, .question = "Does the function handle a request or message that can be retried or delivered more than once, such as a webhook, queue consumer or API handler, and perform a side effect there that must happen once, such as charging, sending or creating a record, with no idempotency key or deduplication? Ignore bookkeeping in memory within one run, and writes that are already idempotent, such as upserts keyed by the data's identity.", .judgement = "A retry or duplicate delivery repeats a side effect that must happen once", .asks = .function },
    .{ .name = "ext-distributed-002", .alias = "EXT-DISTRIBUTED-002", .advice = "Read from a source that provides the guarantee, or handle stale and reordered data.", .severity = .@"error", .tier = .default, .question = "Does the function assume stronger consistency than its storage or messaging provides, such as reading from a replica or cache right after a write and expecting to see it, or relying on message order that is not guaranteed?", .judgement = "The code assumes consistency or ordering the storage does not guarantee", .asks = .function },
    .{ .name = "ext-distributed-003", .alias = "EXT-DISTRIBUTED-003", .advice = "Use an outbox, saga or compensating action so the workflow completes or is undone.", .severity = .@"error", .tier = .default, .question = "Does the function write to more than one system, such as a database and a queue, payment provider or another service, so a failure between writes leaves them inconsistent with no transaction, outbox, saga or compensation?", .judgement = "A failure between writes to different systems leaves them inconsistent", .asks = .function },
    .{ .name = "ext-distributed-004", .alias = "EXT-DISTRIBUTED-004", .advice = "Check the lease before each write, and have storage reject writes with stale fencing tokens.", .severity = .@"error", .tier = .default, .question = "Does the function perform exclusive work under a lease or distributed lock without checking the lease is still held, or without a fencing token, so a paused or slow worker could continue after losing it?", .judgement = "Work can continue after the lease is lost", .asks = .function },
    .{ .name = "ext-delivery-001", .alias = "EXT-DELIVERY-001", .advice = "Use an expand and contract change that supports both versions.", .severity = .warning, .tier = .default, .question = "Does the function change a data format, message, schema or API call in a way that old and new versions running side by side during a deployment could not both handle?", .judgement = "Old and new versions cannot both handle this change during rollout", .asks = .function },
    .{ .name = "ext-delivery-002", .alias = "EXT-DELIVERY-002", .advice = "Reconcile record counts and totals, handle every record, and provide a rollback.", .severity = .@"error", .tier = .default, .question = "Is this a data migration or backfill that could drop, corrupt or lock existing data, for example by skipping records that fail to convert, lacking a rollback or not reconciling counts?", .judgement = "This migration can lose or corrupt existing data", .asks = .function },
    .{ .name = "ext-delivery-003", .alias = "EXT-DELIVERY-003", .advice = "Validate configuration against a schema, including cross-field rules.", .severity = .warning, .tier = .default, .question = "Do these configuration files contain settings that contradict each other or their schema, such as a production endpoint with development credentials, or values of the wrong type or out of range?", .judgement = "Configuration settings contradict each other or their schema", .asks = .project },
    .{ .name = "ext-delivery-004", .alias = "EXT-DELIVERY-004", .advice = "Include everything the restore procedure needs, and rehearse a restore.", .severity = .warning, .tier = .default, .question = "Does the function create a backup, snapshot or release artifact that omits something needed to restore it, such as encryption keys, schema, configuration or dependent data?", .judgement = "The backup or artifact cannot be restored as it is", .asks = .function },
    .{ .name = "ext-arch-001", .alias = "EXT-ARCH-001", .advice = "Depend on an interface in the allowed layer instead.", .severity = .warning, .tier = .default, .question = "Does this file import across an architectural boundary its own layout evidently forbids, such as domain code importing a web framework, database driver or other infrastructure directly?", .judgement = "This file depends across a forbidden architectural boundary", .asks = .file },
    .{ .name = "ext-arch-002", .alias = "EXT-ARCH-002", .advice = "Invert the dependency with an interface or event.", .severity = .warning, .tier = .default, .question = "Does this file, belonging to a lower layer such as storage or domain code, import a higher layer such as a controller, command line or user interface module?", .judgement = "A lower layer imports a higher one, creating a cycle between layers", .asks = .file },
    .{ .name = "ext-arch-003", .alias = "EXT-ARCH-003", .advice = "Use portable APIs, or handle each platform.", .severity = .warning, .tier = .default, .question = "Does the function assume platform behaviour that is not true on every target, such as case-sensitive paths, / separators, a particular shell, line endings or locale?", .judgement = "The code assumes behaviour not available on every target platform", .asks = .function },
    .{ .name = "ext-arch-004", .alias = "EXT-ARCH-004", .advice = "Add the change compatibly, for example as an optional parameter, or release it as a breaking change.", .severity = .warning, .tier = .default, .question = "Does the function change a public interface in a breaking way, such as adding a required parameter, removing or renaming a field, or changing a return type, that existing callers would not expect?", .judgement = "A public interface changes in a breaking way", .asks = .function },
    .{ .name = "ext-verify-001", .alias = "EXT-VERIFY-001", .advice = "Derive expected values independently from the requirement.", .severity = .@"error", .tier = .default, .question = "Is this a test whose expected value is computed the same way as the implementation, or copied from its output, rather than derived independently from the requirement?", .judgement = "The expected value comes from the implementation, so the test repeats its mistakes", .asks = .function },
    .{ .name = "ext-obs-001", .alias = "EXT-OBS-001", .advice = "Record success only after the operation completes.", .severity = .warning, .tier = .default, .question = "Does the function record success, such as a success metric, log or status, before the operation has actually completed, or on a path where it failed?", .judgement = "Success is recorded for an operation that may have failed", .asks = .function },
    .{ .name = "ext-obs-002", .alias = "EXT-OBS-002", .advice = "Pass the trace or request context along with the work.", .severity = .warning, .tier = .default, .question = "Does the function hand work to another thread, task, queue or service without passing along the trace, correlation or request identifier?", .judgement = "The correlation identifier is lost at this handoff", .asks = .function },
    .{ .name = "ext-obs-003", .alias = "EXT-OBS-003", .advice = "Emit a metric, log or alert when it occurs.", .severity = .warning, .tier = .default, .question = "Does the function handle an operational failure, such as a stalled queue, exhausted retries or a dropped message, without emitting any metric, log or alert?", .judgement = "An operational failure happens silently", .asks = .function },
    .{ .name = "ext-obs-004", .alias = "EXT-OBS-004", .advice = "Use bounded labels, and put identifiers in logs or traces.", .severity = .warning, .tier = .default, .question = "Does the function use unbounded values, such as user IDs, request IDs, raw URLs or error messages, as metric labels or tags?", .judgement = "Unbounded values are used as metric labels, which can explode storage", .asks = .function },
    .{ .name = "ext-human-001", .alias = "EXT-HUMAN-001", .advice = "Use semantic controls with labels, and support keyboard operation.", .severity = .warning, .tier = .default, .question = "Does the function render user interface elements for a required action that cannot be used with a keyboard or assistive technology, such as clickable divs without roles, missing labels or mouse-only handlers?", .judgement = "A required interaction is not accessible", .asks = .function },
    .{ .name = "ext-human-002", .alias = "EXT-HUMAN-002", .advice = "Confirm the exact target, and act on that same target.", .severity = .@"error", .tier = .default, .question = "Does the function delete or overwrite data on a user's behalf, such as their files, records or accounts, where the confirmation shown or requested may refer to a different target than the one actually affected, or where no confirmation is required? Ignore removing files, folders or records that the same code or test created earlier in the run, such as temporary files and test fixtures.", .judgement = "The destructive action may not match what the user confirmed", .asks = .function },
    .{ .name = "ext-human-003", .alias = "EXT-HUMAN-003", .advice = "Enforce the safety constraint in this code instead of assuming another component will.", .severity = .@"error", .tier = .default, .question = "Does the function allow a safety-relevant action based on the assumption that another component or controller will block unsafe combinations, with no enforced check of its own?", .judgement = "Unsafe combinations of actions are not prevented here", .asks = .function },
    .{ .name = "ext-human-004", .alias = "EXT-HUMAN-004", .advice = "Name an accountable role and write the runbook.", .severity = .information, .tier = .default, .question = "Do these files describe an operational responsibility, such as recovery, on-call, key rotation or incident response, without naming an owner or giving a procedure to follow?", .judgement = "An operational responsibility has no owner or procedure", .asks = .project },
};
